for _ in range(int(input())):
	n = int(input())
	a = list(map(int, input().split()))
	odd = 0
	even = 0
	for x in a:
		if x % 2 == 0:
			even += 1
		else:
			odd += 1
	if even % 2 == 1 and odd % 4 != 2:
		print('Alice')
	elif even % 2 == 1:
		print('Bob')
	elif 1 <= odd % 4 <= 2:
		print('Bob')
	else:
		print('Alice')
